{"read_file": "import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, rebalance_to_weights

ASSETS = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
# Current screener ensemble; directions are all positive (higher rank is preferred).
FACTORS = {"mom20": .10, "mom30": .08, "resid30": .08, "downmom": .22,
           "eff": .20, "persist": .05, "lead": .15, "rev": .12}
MIN_W, MAX_W = .025, .16
_day = 0

def cs_rank(values):
    valid = [(s, v) for s, v in values.items() if np.isfinite(v)]
    out = {s: .5 for s in ASSETS}
    if len(valid) > 1:
        valid.sort(key=lambda z: z[1])
        for i, (s, _) in enumerate(valid):
            out[s] = (i + 1.0) / len(valid)
    return out

def bounded_weights(score):
    raw = {s: max(.05, float(score.get(s, .5))) for s in ASSETS}
    w = {s: MIN_W + (1 - MIN_W * len(ASSETS)) * raw[s] / sum(raw.values()) for s in ASSETS}
    for _ in range(30):
        excess = sum(max(0., x - MAX_W) for x in w.values())
        if excess < 1e-10:
            break
        capped = {s for s in ASSETS if w[s] >= MAX_W - 1e-10}
        for s in capped:
            w[s] = MAX_W
        free = [s for s in ASSETS if s not in capped]
        if not free:
            break
        denom = sum(raw[s] for s in free)
        for s in free:
            w[s] += excess * raw[s] / denom
    total = sum(w.values())
    return {s: max(0., w[s] / total) for s in ASSETS}

@register_hook
def cross_asset_strategy():
    global _day
    _day += 1
    # One proposal per ten-trading-day block.
    if (_day - 1) % 10 != 0:
        return
    data = {}
    for s in ASSETS:
        df = get_stock_daily_data(symbol=s, days=180)
        if df is None or len(df) < 65:
            continue
        c = np.asarray(df.sort_values("date")["close"], dtype=float)
        if len(c) < 65 or not np.all(np.isfinite(c[-65:])) or c[-1] <= 0:
            continue
        r = c[1:] / np.maximum(c[:-1], 1e-12) - 1.
        vol = max(float(np.std(r[-20:])), .008)
        downside = max(float(np.std(np.minimum(r[-20:], 0.))), .004)
        t20, t30 = c[-1] / c[-21] - 1., c[-1] / c[-31] - 1.
        data[s] = {
            "mom20": t20 / (vol + .01) * (.5 + np.mean(r[-20:] > 0)),
            "mom30": t30 / (vol + .01) * (.5 + np.mean(r[-30:] > 0)),
            "downmom": t20 / (downside + .01),
            "eff": t20 / (downside + .015),
            "persist": t30 / (vol + .01) * np.mean(r[-30:] > 0),
            "lead": c[-1] / c[-6] - 1.,
            "rev": -float(np.mean(r[-5:])),
            "trend": t30, "vol": vol
        }
    if len(data) < 10:
        return
    # Market-residual momentum versus the available equity-index median.
    market = float(np.median([x["trend"] for x in data.values()]))
    for x in data.values():
        x["resid30"] = x["trend"] - market
    ranks = {f: cs_rank({s: data[s][f] for s in data}) for f in FACTORS}
    score = {s: sum(FACTORS[f] * ranks[f][s] for f in FACTORS) for s in ASSETS}

    eq = [data[s] for s in ("000300.SH", "SPX", "HSI", "N225", "SX5E", "NDX") if s in data]
    breadth = sum(x["trend"] > 0 for x in eq) / max(1, len(eq))
    spx = data.get("SPX", {})
    bear = len(eq) >= 3 and (breadth <= .50 or (spx.get("trend", 0.) < 0 and spx.get("lead", 0.) < 0))
    median_vol = float(np.median([x["vol"] for x in data.values()]))
    high_risk = median_vol > .018 or breadth < .67
    if bear or high_risk:
        boost = .16 if bear else .10
        for s in ("XAU", "US10Y", "CN10Y"):
            if s in score:
                score[s] += boost
        for s in ("BTC", "ETH", "WTI"):
            if s in score:
                score[s] = max(.05, score[s] - (.08 if bear else .04))
    # Small inverse-vol overlay avoids concentrating the defensive rank winners.
    for s in ASSETS:
        if s in data:
            score[s] *= .985 + .015 * median_vol / max(data[s]["vol"], .004)
    target = bounded_weights(score)
    if len(target) == len(ASSETS) and abs(sum(target.values()) - 1.) < 1e-8:
        rebalance_to_weights(target)


def strategy():
    return cross_asset_strategy()
"}

